// 개발노트(체인지로그) — 버전별 주요 개발내역.
//
// ⚠️ 버전을 올릴 때(주요 업데이트)마다:
//   1) package.json 의 "version" 을 아래 최신 항목과 동일하게 올린다(헤더 배지 v표시가 여기서 나온다).
//   2) 이 배열 맨 앞에 새 항목을 추가한다(최신이 맨 위).
// 배열 순서 = 최신 → 과거. 헤더의 버전 배지를 클릭하면 이 내용이 개발노트 팝업으로 표시된다.

export interface ChangelogEntry {
  /** 시맨틱 버전 (예: '1.2.0'). 최신 항목은 package.json version 과 일치해야 한다. */
  version: string;
  /** 배포일 (YYYY-MM-DD). */
  date: string;
  /** 한 줄 제목. */
  title: string;
  /** 주요 변경 항목(불릿). */
  highlights: string[];
}

